SELECT v.id, $hk$boe26-d757638789cfefd3fe9c817f$hk$, $hk$تنظيم المؤسسة العامة للري الصادر بقرار مجلس الوزراء رقم (43) وتاريخ 1447/1/13هـ$hk$, $hk$أنظمة الزراعة والمياه والثروات الحية$hk$, v.n, v.title, v.content, $hk$قرار مجلس الوزراء رقم (43) وتاريخ 1447/1/13هـ$hk$, NULL, 'سارية', $hk$2026-10-17T00:00:00Z$hk$::timestamp, $hk$2026-10-17T00:00:00Z$hk$::timestamp, v.sn
FROM (VALUES
($hk$boe26-fe887de541ffa1fc7f2154cd$hk$, 1, $hk$المادة الأولى$hk$, $hk$يقصد بالألفاظ الآتية -أينما وردت في هذا التنظيم- المعاني المبينة أمام كل منها:

المؤسسة: المؤسسة العامة للري.

التنظيم: تنظيم المؤسسة.

الوزير: وزير البيئة والمياه والزراعة.

المجلس: مجلس إدارة المؤسسة.

الرئيس: رئيس المجلس.$hk$, $hk$تنظيم الموسسه العامه للري الصادر بقرار مجلس الوزراء رقم 43 وتاريخ 1447 1 13ه الماده الاولي يقصد بالالفاظ الاتيه اينما وردت في هذا التنظيم المعاني المبينه امام كل منها الموسسه الموسسه العامه للري التنظيم تنظيم الموسسه الوزير وزير البييه والمياه والزراعه المجلس مجلس اداره الموسسه الرييس رييس المجلس انظمه الزراعه والمياه والثروات الحيه$hk$),
($hk$boe26-ee8b2f89eab39d6954038b50$hk$, 2, $hk$المادة الثانية$hk$, $hk$تتمتع المؤسسة بالشخصية الاعتبارية العامة وبالاستقلال المالي والإداري، وترتبط تنظيمياً بالوزير، ويكون مقرها الرئيس في محافظة الأحساء، ولها إنشاء فروع أو مكاتب داخل المملكة بحسب الحاجة.$hk$, $hk$تنظيم الموسسه العامه للري الصادر بقرار مجلس الوزراء رقم 43 وتاريخ 1447 1 13ه الماده الثانيه تتمتع الموسسه بالشخصيه الاعتباريه العامه وبالاستقلال المالي والاداري وترتبط تنظيميا بالوزير ويكون مقرها الرييس في محافظه الاحساء ولها انشاء فروع او مكاتب داخل المملكه بحسب الحاجه انظمه الزراعه والمياه والثروات الحيه$hk$),
($hk$boe26-f1d52c3b8b216367b9598017$hk$, 3, $hk$المادة الثالثة$hk$, $hk$تهدف المؤسسة إلى تنظيم الأعمال والخدمات المتعلقة بنشاط الري ونشاط السدود ونشاط إعادة استخدام المياه المعالجة في المملكة، والرقابة على تلك الأنشطة وتشغيلها وتطويرها.$hk$, $hk$تنظيم الموسسه العامه للري الصادر بقرار مجلس الوزراء رقم 43 وتاريخ 1447 1 13ه الماده الثالثه تهدف الموسسه الي تنظيم الاعمال والخدمات المتعلقه بنشاط الري ونشاط السدود ونشاط اعاده استخدام المياه المعالجه في المملكه والرقابه علي تلك الانشطه وتشغيلها وتطويرها انظمه الزراعه والمياه والثروات الحيه$hk$),
($hk$boe26-87a91a54e61eed77618ff441$hk$, 4, $hk$المادة الرابعة$hk$, $hk$تتولى المؤسسة إدارة نشاط الري ونشاط السدود ونشاط إعادة استخدام المياه المعالجة في المملكة، وتشغيلها وتطويرها. ولها -دون إخلال باختصاصات الجهات الحكومية الأخرى- القيام بكل ما يلزم في سبيل تحقيق أهدافها، ومن ذلك ما يأتي:

وضع السياسات والاستراتيجيات والخطط والبرامج ذات الصلة باختصاصاتها، ومراجعتها وتقويمها والإشراف على تنفيذها، والرفع عما يتطلب استكمال إجراءات نظامية في شأنه.

تقديم خدمات الري والصرف الزراعي، بما في ذلك نقل وتوزيع وبيع المياه المعالجة بجميع استخداماتها: (الزراعية، والصناعية، والحضرية)، وتصميم السدود وإنشاؤها وتطويرها وتشغيلها وصيانتها.

وضع برامج جدولة الري للمحاصيل الزراعية وفق المقننات المائية.

معالجة مياه الصرف الزراعي والاستفادة منها.

وضع وتنفيذ خطط الطوارئ والأزمات لأنشطتها ومواجهة نقص المياه، بالتنسيق مع الجهات ذات العلاقة، ووفقاً للإجراءات النظامية ذات الصلة.

اقتراح مشروعات الأنظمة واللوائح ذات الصلة باختصاصاتها، واقتراح تعديل القائم منها، والرفع عنها وفقاً للإجراءات النظامية.

وضع المعايير ذات الصلة باختصاصاتها، والرفع عما يتطلب وفقاً للإجراءات النظامية.

تطبيق معايير نوعية المياه المستخدمة في أنشطتها ومراقبة مستوى جودتها وجودة التربة الزراعية، ودعم الإصلاح البيئي.

تصميم وإنشاء وتطوير وتشغيل وصيانة مصادر إمداد المياه لأنشطتها بالتنسيق مع الجهات ذات العلاقة.

تصميم وإنشاء وتطوير وتشغيل وصيانة محطات الضخ، وأعمال البنية التحتية لمشاريع أنشطة المؤسسة، وأنظمة الصرف الزراعي.

تطوير التقنيات المعتمدة لرصد استهلاك مياه الري والسدود والمياه المعالجة، وضمان امتثالها لمخصصات وبرامج استخدام المياه، واتخاذ الإجراءات المناسبة لمعالجة حالات عدم الامتثال وفق الأنظمة واللوائح والإجراءات ذات الصلة.

إجراء الدراسات والبحوث ذات الصلة باختصاصاتها بالمشاركة مع الجامعات والمعاهد والجهات المتخصصة.

تبني التقنيات الحديثة لترشيد استخدام مياه الري ومياه السدود والمياه المعالجة.

تمثيل المملكة، أو المشاركة في تمثيلها، في المنظمات والمؤسسات المحلية والإقليمية والدولية ذات العلاقة باختصاصاتها، وفق الإجراءات النظامية.

عقد جلسات عمل وندوات ومؤتمرات ومعارض، والمشاركة فيها.

التنسيق مع الجهات ذات العلاقة لتقديم البرامج والدورات في المجالات ذات الصلة باختصاصاتها، وتأهيل الكوادر البشرية العاملة في هذه المجالات.

توفير قاعدة بيانات ومعلومات إحصائية عن أنشطتها.

الاستثمار بما يحقق أهدافها، وفقاً للإجراءات النظامية.

تحديد المقابل المالي نظير بيع المياه المعالجة والخدمات والأعمال والمنتجات التي تقدمها المؤسسة، وفقاً للأحكام النظامية ذات الصلة.

الترخيص لممارسة الأنشطة ذات الصلة باختصاصات المؤسسة، وفقاً لما تقضي به الأنظمة واللوائح ونحوها ذات الصلة.

تعزيز الإيرادات وتحقيق العوائد على الاستثمار في أصول المؤسسة من داخل المؤسسة أو بالشراكة مع جهات خارجية؛ وفقاً للأحكام النظامية ذات الصلة.

العمل على الاستفادة من المصادر المتاحة لمياه الري ومياه السدود والمياه المعالجة التقليدية وغير التقليدية.$hk$, $hk$تنظيم الموسسه العامه للري الصادر بقرار مجلس الوزراء رقم 43 وتاريخ 1447 1 13ه الماده الرابعه تتولي الموسسه اداره نشاط الري ونشاط السدود ونشاط اعاده استخدام المياه المعالجه في المملكه وتشغيلها وتطويرها ولها دون اخلال باختصاصات الجهات الحكوميه الاخري القيام بكل ما يلزم في سبيل تحقيق اهدافها ومن ذلك ما ياتي وضع السياسات والاستراتيجيات والخطط والبرامج ذات الصله باختصاصاتها ومراجعتها وتقويمها والاشراف علي تنفيذها والرفع عما يتطلب استكمال اجراءات نظاميه في شانه تقديم خدمات الري والصرف الزراعي بما في ذلك نقل وتوزيع وبيع المياه المعالجه بجميع استخداماتها الزراعيه والصناعيه والحضريه وتصميم السدود وانشاوها وتطويرها وتشغيلها وصيانتها وضع برامج جدوله الري للمحاصيل الزراعيه وفق المقننات الماييه معالجه مياه الصرف الزراعي والاستفاده منها وضع وتنفيذ خطط الطواري والازمات لانشطتها ومواجهه نقص المياه بالتنسيق مع الجهات ذات العلاقه ووفقا للاجراءات النظاميه ذات الصله اقتراح مشروعات الانظمه واللوايح ذات الصله باختصاصاتها واقتراح تعديل القايم منها والرفع عنها وفقا للاجراءات النظاميه وضع المعايير ذات الصله باختصاصاتها والرفع عما يتطلب وفقا للاجراءات النظاميه تطبيق معايير نوعيه المياه المستخدمه في انشطتها ومراقبه مستوي جودتها وجوده التربه الزراعيه ودعم الاصلاح البييي تصميم وانشاء وتطوير وتشغيل وصيانه مصادر امداد المياه لانشطتها بالتنسيق مع الجهات ذات العلاقه تصميم وانشاء وتطوير وتشغيل وصيانه محطات الضخ واعمال البنيه التحتيه لمشاريع انشطه الموسسه وانظمه الصرف الزراعي تطوير التقنيات المعتمده لرصد استهلاك مياه الري والسدود والمياه المعالجه وضمان امتثالها لمخصصات وبرامج استخدام المياه واتخاذ الاجراءات المناسبه لمعالجه حالات عدم الامتثال وفق الانظمه واللوايح والاجراءات ذات الصله اجراء الدراسات والبحوث ذات الصله باختصاصاتها بالمشاركه مع الجامعات والمعاهد والجهات المتخصصه تبني التقنيات الحديثه لترشيد استخدام مياه الري ومياه السدود والمياه المعالجه تمثيل المملكه او المشاركه في تمثيلها في المنظمات والموسسات المحليه والاقليميه والدوليه ذات العلاقه باختصاصاتها وفق الاجراءات النظاميه عقد جلسات عمل وندوات وموتمرات ومعارض والمشاركه فيها التنسيق مع الجهات ذات العلاقه لتقديم البرامج والدورات في المجالات ذات الصله باختصاصاتها وتاهيل الكوادر البشريه العامله في هذه المجالات توفير قاعده بيانات ومعلومات احصاييه عن انشطتها الاستثمار بما يحقق اهدافها وفقا للاجراءات النظاميه تحديد المقابل المالي نظير بيع المياه المعالجه والخدمات والاعمال والمنتجات التي تقدمها الموسسه وفقا للاحكام النظاميه ذات الصله الترخيص لممارسه الانشطه ذات الصله باختصاصات الموسسه وفقا لما تقضي به الانظمه واللوايح ونحوها ذات الصله تعزيز الايرادات وتحقيق العوايد علي الاستثمار في اصول الموسسه من داخل الموسسه او بالشراكه مع جهات خارجيه وفقا للاحكام النظاميه ذات الصله العمل علي الاستفاده من المصادر المتاحه لمياه الري ومياه السدود والمياه المعالجه التقليديه وغير التقليديه انظمه الزراعه والمياه والثروات الحيه$hk$),
($hk$boe26-16291e9ac09f4b4b2aa1ac7e$hk$, 5, $hk$المادة الخامسة$hk$, $hk$يكون للمؤسسة مجلس إدارة برئاسة الوزير وعضوية كل من:

أ- ممثل من وزارة الاقتصاد والتخطيط.

ب- ممثل من وزارة المالية.

ج- ممثل من وزارة البيئة والمياه والزراعة

د- ممثل من صندوق التنمية الزراعية.

هـ- الرئيس التنفيذي للمؤسسة.

و- الرئيس التنفيذي لشركة المياه الوطنية.

ز- اثنين من ذوي الخبرة والاختصاص في مجال عمل المؤسسة، يصدر بتسميتهما أمر من رئيس مجلس الوزراء بناءً على ترشيح من رئيس المجلس.

فيما عدا الرئيس والعضوين المشار إليهما في الفقرتين الفرعيتين (ه) و(و) من الفقرة (1) من هذه المادة، تكون مدة العضوية في المجلس (ثلاث) سنوات قابلة للتجديد لمدة مماثلة ولمرة واحدة.

يجب ألا تقل مرتبة ممثلي الجهات الحكومية عن المرتبة (الرابعة عشرة)، أو ما يعادلها.

يختار الرئيس نائباً له من ممثلي الجهات الحكومية عدا الرئيس التنفيذي للمؤسسة.$hk$, $hk$تنظيم الموسسه العامه للري الصادر بقرار مجلس الوزراء رقم 43 وتاريخ 1447 1 13ه الماده الخامسه يكون للموسسه مجلس اداره برياسه الوزير وعضويه كل من ا ممثل من وزاره الاقتصاد والتخطيط ب ممثل من وزاره الماليه ج ممثل من وزاره البييه والمياه والزراعه د ممثل من صندوق التنميه الزراعيه ه الرييس التنفيذي للموسسه و الرييس التنفيذي لشركه المياه الوطنيه ز اثنين من ذوي الخبره والاختصاص في مجال عمل الموسسه يصدر بتسميتهما امر من رييس مجلس الوزراء بناء علي ترشيح من رييس المجلس فيما عدا الرييس والعضوين المشار اليهما في الفقرتين الفرعيتين ه و و من الفقره 1 من هذه الماده تكون مده العضويه في المجلس ثلاث سنوات قابله للتجديد لمده مماثله ولمره واحده يجب الا تقل مرتبه ممثلي الجهات الحكوميه عن المرتبه الرابعه عشره او ما يعادلها يختار الرييس نايبا له من ممثلي الجهات الحكوميه عدا الرييس التنفيذي للموسسه انظمه الزراعه والمياه والثروات الحيه$hk$),
($hk$boe26-2ca60297b64210c90cd63878$hk$, 6, $hk$المادة السادسة$hk$, $hk$المجلس هو السلطة المهيمنة على شؤون المؤسسة، ويشرف على إدارتها وتصريف شؤونها، ويتخذ جميع القرارات اللازمة لتحقيق أغراضها في حدود أحكام التنظيم، وله على وجه خاص ما يأتي:

الإشراف على تنفيذ المؤسسة المهمات المنوطة بها.

إقرار السياسات والاستراتيجيات المتعلقة باختصاصات المؤسسة، والخطط والبرامج اللازمة لتنفيذها، والرفع عما يتطلب استكمال إجراءات نظامية في شأنه.

اقتراح مشروعات الأنظمة واللوائح ذات الصلة باختصاصات المؤسسة، واقتراح تعديل القائم منها، والرفع عما يستلزم وفقاً للإجراءات النظامية.

إقرار المعايير ذات الصلة باختصاصات المؤسسة، والرفع عما يستلزم وفقاً للإجراءات النظامية.

النظر في التقارير الدورية التي تقدم إليه عن سير العمل في المؤسسة.

إقرار الهيكل والدليل التنظيمي للمؤسسة.

إقرار اللوائح المالية والإدارية التي تسير عليها المؤسسة، وغيرها من اللوائح الداخلية اللازمة لتسيير شؤونها. ويكون إقرار اللوائح المالية والأحكام ذات الأثر المالي في اللوائح الأخرى بالاتفاق مع وزارة المالية، وإقرار اللوائح الإدارية بالاتفاق مع وزارة الموارد البشرية والتنمية الاجتماعية.

إقرار مكافآت ومزايا من تستعين بهم المؤسسة من الخبراء المختصين ذوي الكفايات المطلوبة، وفقاً للأحكام النظامية ذات الصلة.

تحديد المقابل المالي للخدمات والأعمال والمنتجات والتراخيص التي تقدمها المؤسسة.

الموافقة على مشروع ميزانية المؤسسة وحسابها الختامي وتقرير مراجع الحسابات والتقرير السنوي، تمهيداً لرفعها بحسب الإجراءات النظامية.

إقرار سياسات الاستثمار بالمؤسسة بما يحقق أهدافها، وفقاً للأحكام النظامية ذات الصلة.

قبول الوصايا والهبات والتبرعات وريع الأوقاف والمنح التي تقدم إلى المؤسسة، وفقاً للأحكام المنظمة لذلك.

الموافقة على إبرام الاتفاقيات ومذكرات التفاهم والعقود، بحسب الإجراءات النظامية.

تعيين مراجع حسابات خارجي، ومراقب مالي داخلي.

تعيين أمين عام للمجلس.

وللمجلس تشكيل لجان دائمة أو مؤقتة، من أعضائه أو من سواهم، يعهد إليها بما يراه من مهمات، ويحدد في قرار تشكيل كل لجنة رئيسها وأعضاؤها واختصاصاتها، ويكون لها الاستعانة بمن تراه لتأدية المهمات الموكولة إليها.

وللمجلس تفويض بعض اختصاصاته -عدا الاختصاصات الواردة في الفقرات (2) و(5) و(6) و(7) و(9) و(10) و(11) و(14) من هذه المادة- إلى من يراه من المسؤولين في المؤسسة.$hk$, $hk$تنظيم الموسسه العامه للري الصادر بقرار مجلس الوزراء رقم 43 وتاريخ 1447 1 13ه الماده السادسه المجلس هو السلطه المهيمنه علي شوون الموسسه ويشرف علي ادارتها وتصريف شوونها ويتخذ جميع القرارات اللازمه لتحقيق اغراضها في حدود احكام التنظيم وله علي وجه خاص ما ياتي الاشراف علي تنفيذ الموسسه المهمات المنوطه بها اقرار السياسات والاستراتيجيات المتعلقه باختصاصات الموسسه والخطط والبرامج اللازمه لتنفيذها والرفع عما يتطلب استكمال اجراءات نظاميه في شانه اقتراح مشروعات الانظمه واللوايح ذات الصله باختصاصات الموسسه واقتراح تعديل القايم منها والرفع عما يستلزم وفقا للاجراءات النظاميه اقرار المعايير ذات الصله باختصاصات الموسسه والرفع عما يستلزم وفقا للاجراءات النظاميه النظر في التقارير الدوريه التي تقدم اليه عن سير العمل في الموسسه اقرار الهيكل والدليل التنظيمي للموسسه اقرار اللوايح الماليه والاداريه التي تسير عليها الموسسه وغيرها من اللوايح الداخليه اللازمه لتسيير شوونها ويكون اقرار اللوايح الماليه والاحكام ذات الاثر المالي في اللوايح الاخري بالاتفاق مع وزاره الماليه واقرار اللوايح الاداريه بالاتفاق مع وزاره الموارد البشريه والتنميه الاجتماعيه اقرار مكافات ومزايا من تستعين بهم الموسسه من الخبراء المختصين ذوي الكفايات المطلوبه وفقا للاحكام النظاميه ذات الصله تحديد المقابل المالي للخدمات والاعمال والمنتجات والتراخيص التي تقدمها الموسسه الموافقه علي مشروع ميزانيه الموسسه وحسابها الختامي وتقرير مراجع الحسابات والتقرير السنوي تمهيدا لرفعها بحسب الاجراءات النظاميه اقرار سياسات الاستثمار بالموسسه بما يحقق اهدافها وفقا للاحكام النظاميه ذات الصله قبول الوصايا والهبات والتبرعات وريع الاوقاف والمنح التي تقدم الي الموسسه وفقا للاحكام المنظمه لذلك الموافقه علي ابرام الاتفاقيات ومذكرات التفاهم والعقود بحسب الاجراءات النظاميه تعيين مراجع حسابات خارجي ومراقب مالي داخلي تعيين امين عام للمجلس وللمجلس تشكيل لجان دايمه او موقته من اعضايه او من سواهم يعهد اليها بما يراه من مهمات ويحدد في قرار تشكيل كل لجنه رييسها واعضاوها واختصاصاتها ويكون لها الاستعانه بمن تراه لتاديه المهمات الموكوله اليها وللمجلس تفويض بعض اختصاصاته عدا الاختصاصات الوارده في الفقرات 2 و 5 و 6 و 7 و 9 و 10 و 11 و 14 من هذه الماده الي من يراه من المسوولين في الموسسه انظمه الزراعه والمياه والثروات الحيه$hk$),
($hk$boe26-da645b66d58f43883d12462f$hk$, 7, $hk$المادة السابعة$hk$, $hk$تعقد اجتماعات المجلس في مقر المؤسسة أو في أي مكان آخر في المملكة، برئاسة الرئيس أو من ينيبه من أعضاء المجلس ممثلي الجهات الحكومية ما عدا الرئيس التنفيذي للمؤسسة.

يعقد المجلس اجتماعاته بصفة دورية، على ألا تقل عن (اجتماعين) في السنة. وللرئيس الدعوة للاجتماع متى دعت الحاجة إلى ذلك، أو متى طلب ذلك (ثلث) أعضاء المجلس على الأقل، وتوجه الدعوة إلى الاجتماع من الرئيس، أو من ينيبه، كتابة قبل الاجتماع بـ(سبعة) أيام على الأقل، على أن تتضمن الدعوة جدول أعمال الاجتماع ومكانه.

يكون اجتماع المجلس صحيحاً إذا حضره أغلبية أعضائه على الأقل، بمن فيهم الرئيس أو من ينيبه، وتصدر القرارات بأغلبية أصوات الحاضرين على الأقل، وعند التساوي يرجح الجانب الذي صوت معه رئيس الاجتماع.

يجوز للمجلس -عند الحاجة ووفقاً لما يقدره الرئيس- أن يعقد الاجتماعات وأن يصوت على التوصيات والقرارات عن بُعد من خلال استخدام وسائل التقنية، ويمكن أن تتخذ التوصيات والقرارات عن طريق التمرير على الأعضاء، ويوقع عليها بما يفيد باطلاع جميع الأعضاء عليها، ولا تعد التوصيات والقرارات الصادرة بهاتين الطريقتين صحيحة ما لم تمرر على جميع أعضاء المجلس، ويصوتوا عليها، وتحز على أغلبية أصواتهم على الأقل.

للمجلس دعوة من يراه لحضور اجتماعاته لتقديم معلومات أو آراء أو إيضاحات دون أن يكون له حق التصويت.

لا يجوز للعضو أن يمتنع عن التصويت، أو أن يفوض عضواً آخر للتصويت نيابةً عنه عند غيابه، وللعضو المعترض تسجيل اعتراضه وأسبابه ضمن محضر الاجتماع.

تثبت مداولات المجلس وتوصياته وقراراته في محاضر يوقعها رئيس الاجتماع والأعضاء الحاضرون.

لا يجوز للعضو أن يفشي شيئاً مما اطلع عليه من أسرار المؤسسة بسبب عضويته في المجلس.

يتولى أمين عام المجلس الإعداد لجداول الأعمال ومحاضر الاجتماعات والتوصيات والقرارات.$hk$, $hk$تنظيم الموسسه العامه للري الصادر بقرار مجلس الوزراء رقم 43 وتاريخ 1447 1 13ه الماده السابعه تعقد اجتماعات المجلس في مقر الموسسه او في اي مكان اخر في المملكه برياسه الرييس او من ينيبه من اعضاء المجلس ممثلي الجهات الحكوميه ما عدا الرييس التنفيذي للموسسه يعقد المجلس اجتماعاته بصفه دوريه علي الا تقل عن اجتماعين في السنه وللرييس الدعوه للاجتماع متي دعت الحاجه الي ذلك او متي طلب ذلك ثلث اعضاء المجلس علي الاقل وتوجه الدعوه الي الاجتماع من الرييس او من ينيبه كتابه قبل الاجتماع ب سبعه ايام علي الاقل علي ان تتضمن الدعوه جدول اعمال الاجتماع ومكانه يكون اجتماع المجلس صحيحا اذا حضره اغلبيه اعضايه علي الاقل بمن فيهم الرييس او من ينيبه وتصدر القرارات باغلبيه اصوات الحاضرين علي الاقل وعند التساوي يرجح الجانب الذي صوت معه رييس الاجتماع يجوز للمجلس عند الحاجه ووفقا لما يقدره الرييس ان يعقد الاجتماعات وان يصوت علي التوصيات والقرارات عن بعد من خلال استخدام وسايل التقنيه ويمكن ان تتخذ التوصيات والقرارات عن طريق التمرير علي الاعضاء ويوقع عليها بما يفيد باطلاع جميع الاعضاء عليها ولا تعد التوصيات والقرارات الصادره بهاتين الطريقتين صحيحه ما لم تمرر علي جميع اعضاء المجلس ويصوتوا عليها وتحز علي اغلبيه اصواتهم علي الاقل للمجلس دعوه من يراه لحضور اجتماعاته لتقديم معلومات او اراء او ايضاحات دون ان يكون له حق التصويت لا يجوز للعضو ان يمتنع عن التصويت او ان يفوض عضوا اخر للتصويت نيابه عنه عند غيابه وللعضو المعترض تسجيل اعتراضه واسبابه ضمن محضر الاجتماع تثبت مداولات المجلس وتوصياته وقراراته في محاضر يوقعها رييس الاجتماع والاعضاء الحاضرون لا يجوز للعضو ان يفشي شييا مما اطلع عليه من اسرار الموسسه بسبب عضويته في المجلس يتولي امين عام المجلس الاعداد لجداول الاعمال ومحاضر الاجتماعات والتوصيات والقرارات انظمه الزراعه والمياه والثروات الحيه$hk$),
($hk$boe26-7c46e5690767b0c5bfc80785$hk$, 8, $hk$المادة الثامنة$hk$, $hk$يكون للمؤسسة رئيس تنفيذي يعين ويعفى بقرار من المجلس، ويكون المسؤول عن إدارة المؤسسة، وتتركز مسؤولياته في حدود ما ينص عليه التنظيم وما يقرره المجلس، ويتولى مباشرة الاختصاصات الآتية:

اقتراح السياسات والاستراتيجيات المتعلقة باختصاصات المؤسسة، والخطط والبرامج اللازمة لتنفيذها، ورفعها إلى المجلس؛ للنظر في إقرارها.

الإشراف على سير العمل في المؤسسة من خلال اللوائح والخطط والبرامج المعتمدة.

اقتراح هيكل المؤسسة ودليلها التنظيمي، واللوائح المالية والإدارية التي تسير عليها المؤسسة وغيرها من اللوائح الداخلية اللازمة لتسيير شؤونها، ورفعها إلى المجلس؛ للنظر في إقرارها.

تنفيذ القرارات التي يصدرها المجلس.

الإشراف على إعداد مشروع ميزانية المؤسسة السنوية ومشروع حسابها الختامي والتقرير السنوي، ورفعها إلى المجلس؛ للنظر في إقرارها.

تعيين العاملين في المؤسسة وفقاً للصلاحيات الممنوحة له، والإشراف عليهم.

الصرف من الميزانية المعتمدة للمؤسسة، واتخاذ جميع الإجراءات المالية وفقاً للأنظمة واللوائح المعتمدة والصلاحيات التي فوضها إليه المجلس.

إعداد التقارير الخاصة بتنفيذ خطط المؤسسة وبرامجها ومنجزاتها، وعرضها على المجلس.

التوقيع على الاتفاقيات ومذكرات التفاهم والعقود، وفقاً للإجراءات النظامية ذات الصلة.

التعاقد لتنفيذ الأعمال والخدمات والمهمات المنوطة بالمؤسسة متى ما دعت الحاجة، وغيرها من الأعمال والخدمات، وفقاً للأنظمة والصلاحيات التي فوضها إليه المجلس.

تنظيم مشاركة المؤسسة في المؤتمرات والفعاليات والمهرجانات والمعارض الإقليمية والدولية، وفقاً للإجراءات النظامية.

إصدار القرارات اللازمة لتنفيذ أحكام التنظيم واللوائح الصادرة بناءً عليه والقواعد والإجراءات المعتمدة، بحسب الصلاحيات المخولة له.

تمثيل المؤسسة أمام القضاء، ولدى الجهات الحكومية والمؤسسات والهيئات الأخرى ذات العلاقة، وغيرها من الجهات داخل المملكة وخارجها، وله تفويض غيره بذلك.

اقتراح مكافآت ومزايا من تستعين بهم المؤسسة من الخبراء المختصين ذوي الكفايات المطلوبة، والرفع عن ذلك إلى المجلس؛ للنظر في إقرارها.

أي اختصاص آخر يسنده إليه المجلس.

وللرئيس أن يفوض بعض اختصاصاته إلى من يراه من منسوبي المؤسسة.$hk$, $hk$تنظيم الموسسه العامه للري الصادر بقرار مجلس الوزراء رقم 43 وتاريخ 1447 1 13ه الماده الثامنه يكون للموسسه رييس تنفيذي يعين ويعفي بقرار من المجلس ويكون المسوول عن اداره الموسسه وتتركز مسوولياته في حدود ما ينص عليه التنظيم وما يقرره المجلس ويتولي مباشره الاختصاصات الاتيه اقتراح السياسات والاستراتيجيات المتعلقه باختصاصات الموسسه والخطط والبرامج اللازمه لتنفيذها ورفعها الي المجلس للنظر في اقرارها الاشراف علي سير العمل في الموسسه من خلال اللوايح والخطط والبرامج المعتمده اقتراح هيكل الموسسه ودليلها التنظيمي واللوايح الماليه والاداريه التي تسير عليها الموسسه وغيرها من اللوايح الداخليه اللازمه لتسيير شوونها ورفعها الي المجلس للنظر في اقرارها تنفيذ القرارات التي يصدرها المجلس الاشراف علي اعداد مشروع ميزانيه الموسسه السنويه ومشروع حسابها الختامي والتقرير السنوي ورفعها الي المجلس للنظر في اقرارها تعيين العاملين في الموسسه وفقا للصلاحيات الممنوحه له والاشراف عليهم الصرف من الميزانيه المعتمده للموسسه واتخاذ جميع الاجراءات الماليه وفقا للانظمه واللوايح المعتمده والصلاحيات التي فوضها اليه المجلس اعداد التقارير الخاصه بتنفيذ خطط الموسسه وبرامجها ومنجزاتها وعرضها علي المجلس التوقيع علي الاتفاقيات ومذكرات التفاهم والعقود وفقا للاجراءات النظاميه ذات الصله التعاقد لتنفيذ الاعمال والخدمات والمهمات المنوطه بالموسسه متي ما دعت الحاجه وغيرها من الاعمال والخدمات وفقا للانظمه والصلاحيات التي فوضها اليه المجلس تنظيم مشاركه الموسسه في الموتمرات والفعاليات والمهرجانات والمعارض الاقليميه والدوليه وفقا للاجراءات النظاميه اصدار القرارات اللازمه لتنفيذ احكام التنظيم واللوايح الصادره بناء عليه والقواعد والاجراءات المعتمده بحسب الصلاحيات المخوله له تمثيل الموسسه امام القضاء ولدي الجهات الحكوميه والموسسات والهييات الاخري ذات العلاقه وغيرها من الجهات داخل المملكه وخارجها وله تفويض غيره بذلك اقتراح مكافات ومزايا من تستعين بهم الموسسه من الخبراء المختصين ذوي الكفايات المطلوبه والرفع عن ذلك الي المجلس للنظر في اقرارها اي اختصاص اخر يسنده اليه المجلس وللرييس ان يفوض بعض اختصاصاته الي من يراه من منسوبي الموسسه انظمه الزراعه والمياه والثروات الحيه$hk$),
($hk$boe26-17aa39d2673daf3d77742e6e$hk$, 9, $hk$المادة التاسعة$hk$, $hk$تتكون موارد المؤسسة المالية مما يأتي:

ما يخصص لها في الميزانية العامة للدولة.

المقابل المالي الذي تستوفيه نظير الخدمات والأعمال والمنتجات والتراخيص التي تقدمها.

عوائد استثماراتها.

ما يقبله المجلس من هبات وتبرعات ومنح ووصايا وريع أوقاف، وفقاً للإجراءات النظامية ذات الصلة.

أي مورد آخر يقره المجلس بما لا يخالف الأنظمة والتعليمات. $hk$, $hk$تنظيم الموسسه العامه للري الصادر بقرار مجلس الوزراء رقم 43 وتاريخ 1447 1 13ه الماده التاسعه تتكون موارد الموسسه الماليه مما ياتي ما يخصص لها في الميزانيه العامه للدوله المقابل المالي الذي تستوفيه نظير الخدمات والاعمال والمنتجات والتراخيص التي تقدمها عوايد استثماراتها ما يقبله المجلس من هبات وتبرعات ومنح ووصايا وريع اوقاف وفقا للاجراءات النظاميه ذات الصله اي مورد اخر يقره المجلس بما لا يخالف الانظمه والتعليمات انظمه الزراعه والمياه والثروات الحيه$hk$),
($hk$boe26-cc60ca9fd602110fdf8340c8$hk$, 10, $hk$المادة العاشرة$hk$, $hk$تودع أموال المؤسسة في حساب جاري وزارة المالية في البنك المركزي السعودي.

تفتح المؤسسة حساباً لها في البنك المركزي السعودي، ولها فتح حسابات أخرى في أي من البنوك المرخص لها بالعمل في المملكة، ويصرف من هذه الحسابات وفق ميزانية المؤسسة ولوائحها المالية المعتمدة.$hk$, $hk$تنظيم الموسسه العامه للري الصادر بقرار مجلس الوزراء رقم 43 وتاريخ 1447 1 13ه الماده العاشره تودع اموال الموسسه في حساب جاري وزاره الماليه في البنك المركزي السعودي تفتح الموسسه حسابا لها في البنك المركزي السعودي ولها فتح حسابات اخري في اي من البنوك المرخص لها بالعمل في المملكه ويصرف من هذه الحسابات وفق ميزانيه الموسسه ولوايحها الماليه المعتمده انظمه الزراعه والمياه والثروات الحيه$hk$),
($hk$boe26-ac8beedbb4c23066c0aabe92$hk$, 11, $hk$المادة الحادية عشرة$hk$, $hk$تكون للمؤسسة ميزانية سنوية مستقلة.

السنة المالية للمؤسسة هي السنة المالية للدولة.$hk$, $hk$تنظيم الموسسه العامه للري الصادر بقرار مجلس الوزراء رقم 43 وتاريخ 1447 1 13ه الماده الحاديه عشره تكون للموسسه ميزانيه سنويه مستقله السنه الماليه للموسسه هي السنه الماليه للدوله انظمه الزراعه والمياه والثروات الحيه$hk$),
($hk$boe26-fba641d6d68ae26676b02ee9$hk$, 12, $hk$المادة الثانية عشرة$hk$, $hk$دون إخلال باختصاص الديوان العام للمحاسبة في الرقابة على حسابات المؤسسة وعملياتها، يعين المجلس مراجع حسابات خارجياً (أو أكثر) من المرخص لهم بالعمل في المملكة، لتدقيق حسابات المؤسسة ومعاملاتها وبياناتها وميزانيتها السنوية وحساباتها الختامية، ويحدد المجلس أتعابه. ويرفع تقرير مراجع الحسابات إلى المجلس، ويزود الديوان العام للمحاسبة بنسخة منه بعد اعتماده من المجلس.$hk$, $hk$تنظيم الموسسه العامه للري الصادر بقرار مجلس الوزراء رقم 43 وتاريخ 1447 1 13ه الماده الثانيه عشره دون اخلال باختصاص الديوان العام للمحاسبه في الرقابه علي حسابات الموسسه وعملياتها يعين المجلس مراجع حسابات خارجيا او اكثر من المرخص لهم بالعمل في المملكه لتدقيق حسابات الموسسه ومعاملاتها وبياناتها وميزانيتها السنويه وحساباتها الختاميه ويحدد المجلس اتعابه ويرفع تقرير مراجع الحسابات الي المجلس ويزود الديوان العام للمحاسبه بنسخه منه بعد اعتماده من المجلس انظمه الزراعه والمياه والثروات الحيه$hk$),
($hk$boe26-ffc73bc20478832c611a6816$hk$, 13, $hk$المادة الثالثة عشرة$hk$, $hk$يخضع منسوبو المؤسسة لأحكام نظام العمل، ونظام التأمينات الاجتماعية. $hk$, $hk$تنظيم الموسسه العامه للري الصادر بقرار مجلس الوزراء رقم 43 وتاريخ 1447 1 13ه الماده الثالثه عشره يخضع منسوبو الموسسه لاحكام نظام العمل ونظام التامينات الاجتماعيه انظمه الزراعه والمياه والثروات الحيه$hk$),
($hk$boe26-0d5ec47da4d2394686d0a68b$hk$, 14, $hk$المادة الرابعة عشرة$hk$, $hk$ترفع المؤسسة إلى رئيس مجلس الوزراء -خلال (تسعين) يوماً من بداية كل سنة مالية- تقريراً سنوياً عما حققته من إنجازات خلال السنة المنقضية وما واجهها من صعوبات وما تراه من مقترحات لتحسين سير العمل بها.$hk$, $hk$تنظيم الموسسه العامه للري الصادر بقرار مجلس الوزراء رقم 43 وتاريخ 1447 1 13ه الماده الرابعه عشره ترفع الموسسه الي رييس مجلس الوزراء خلال تسعين يوما من بدايه كل سنه ماليه تقريرا سنويا عما حققته من انجازات خلال السنه المنقضيه وما واجهها من صعوبات وما تراه من مقترحات لتحسين سير العمل بها انظمه الزراعه والمياه والثروات الحيه$hk$),
($hk$boe26-1ea7c5884e6a645ceb8c2a85$hk$, 15, $hk$المادة الخامسة عشرة$hk$, $hk$ترفع المؤسسة إلى رئيس مجلس الوزراء حسابها الختامي السنوي خلال (تسعين) يوماً من تاريخ انتهاء السنة المالية. $hk$, $hk$تنظيم الموسسه العامه للري الصادر بقرار مجلس الوزراء رقم 43 وتاريخ 1447 1 13ه الماده الخامسه عشره ترفع الموسسه الي رييس مجلس الوزراء حسابها الختامي السنوي خلال تسعين يوما من تاريخ انتهاء السنه الماليه انظمه الزراعه والمياه والثروات الحيه$hk$),
($hk$boe26-71da20f3b86cbd96c5d174f3$hk$, 16, $hk$المادة السادسة عشرة$hk$, $hk$ينشر التنظيم في الجريدة الرسمية، ويعمل به من تاريخ نشره.$hk$, $hk$تنظيم الموسسه العامه للري الصادر بقرار مجلس الوزراء رقم 43 وتاريخ 1447 1 13ه الماده السادسه عشره ينشر التنظيم في الجريده الرسميه ويعمل به من تاريخ نشره انظمه الزراعه والمياه والثروات الحيه$hk$)
) AS v(id, n, title, content, sn);

